import{z as s,x as A,o,c as p,q as n,j as r,D as e,d as i,s as l,S as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"词表大小与压缩率","description":"","frontmatter":{"title":"词表大小与压缩率","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vocab-compression.md","filePath":"llm/vocab-compression.md","lastUpdated":1791413859000}'),d={name:"llm/vocab-compression.md"};function m(B,a,k,h,c,_){const t=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=n('<h1 id="词表大小与压缩率" tabindex="-1">词表大小与压缩率 <a class="header-anchor" href="#词表大小与压缩率" aria-label="Permalink to &quot;词表大小与压缩率&quot;">​</a></h1><div class="epigraph"><p>词表越大，同样字符能编成越短的整数序列；嵌入与 softmax 也越贵，且名额一旦分给高频垃圾合并，低资源语言与稀有符号就被挤出短 token。</p><footer>—— 由 BPE / Unigram / ByT5 的符号设计直接推出的计算权衡</footer></div><p><a href="/llm/tokenizer-design">上一课</a>把 BPE 写成频次贪心合并、Unigram 写成按子词似然删词、ByT5 写成几乎在原始字节上建模；预分词决定哪些边界不可跨。缺口是词表大小 \\(V\\)：它同时买压缩率（更短序列）和付嵌入 / softmax 税，最优随模型规模与语言中心移动。按 token 的配比不等于按字符的配比；假压缩来自未去重模板。本课写 \\(V\\) 怎么选、压缩率如何分桶度量。不重推合并规则。后课优化器默认已经读完：词表训练必须放在清洗去重之后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记语料字符数为 \\(C\\)，切分后 token 数为 \\(T\\)，压缩率可用 \\(C/T\\)（字符每 token）或 \\(T/C\\) 的倒数来报。英语子词常见落在每 token 约四字符量级，中文往往接近每 token 一字，代码视标识符是否被收成原子而剧烈波动。同一 \\(V\\)，不同语言压缩率可以差一倍以上，于是「按 token 的 10% 多语言」在字符意义上完全不是 10%。配比若只盯 token，会系统性少给切得碎的语言。</p><p><span class="marginnote">直觉类比菜单页数：词表名额像菜单的页数——页数多，点菜一句话说得短；但印菜单贵（嵌入与 softmax），而且若整页都给了「单人套餐模板」这类高频垃圾，真正常点的菜反而排不进短句。名额给谁，和给多少一样重要。</span></p><p>\\(V\\) 太小，序列变长：上下文窗口浪费在碎片上，长程依赖更难，训练与推理的 FLOPs 按 token 上涨。\\(V\\) 太大，嵌入占用显存，softmax 变慢（即使有采样或分层也增加复杂度），大量符号在预训练里只出现几次，估计噪声大。还存在「假压缩」：把网页模板整句收成单 token，\\(C/T\\) 很好看，对语言建模无益。去重之后再训 tokenizer，就是为了避免这种假压缩。</p><h3 id="度量必须分桶" tabindex="-1">度量必须分桶 <a class="header-anchor" href="#度量必须分桶" aria-label="Permalink to &quot;度量必须分桶&quot;">​</a></h3><p>总体 \\(C/T\\) 会被英语网页主导。应分语言、分代码、分数学公式报压缩率，并报百分位而不是只报均值。极端长尾（URL、base64、十六进制）会把均值拉歪。过滤掉这些垃圾（C4 / FineWeb 的启发式）会同时改善质量和压缩统计——二者纠缠，不要把过滤带来的 \\(C/T\\) 上升全算成词表的功劳。<span class="marginnote">上下文长度标称 8K token，对英语和对字节级中文覆盖的字符数可以差数倍。长上下文论文若只报 token 长度、不报字符或文档覆盖，跨词表不可比。这与缩放定律同一教训：横轴必须定义清楚。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践中在清洗去重后的混合物上训练若干 \\(V\\)（例如 32K、50K、100K、128K），画出：嵌入参数量、\\(C/T\\)、各语种 \\(C/T\\)、一份固定文档集上的序列长度分布、以及小模型在固定 token 预算与固定字符预算下的损失。固定 token 预算偏向高压缩词表；固定字符预算才接近「读同样多的文本」。大模型最终常在 32K 到 128K 之间折中：Llama 早期偏小词表，后来为多语言与特殊 token 放大。这不是定律，而是产品轴上的点。</p><p>ByT5 提供下界对照：\\(V\\approx 256\\) 时压缩率按 UTF-8 字节计约为 1，序列最长，嵌入最便宜。若某子词方案相对字节的加速，主要来自更短序列而不是更好的归纳偏置，那么一旦推理内存墙在 KV 而不在嵌入，\\(V\\) 仍值得加大。反之，若模型已经很小、嵌入占参数一半，再加大 \\(V\\) 是亏的。</p>',12)),(o(),r(E,null,{default:e(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22%E8%AF%8D%E8%A1%A8%E5%A4%A7%E5%B0%8F%20V%22%5D%20--%3E%20E%5B%22%E5%B5%8C%E5%85%A5%20%2F%20Softmax%20%E5%8F%82%E6%95%B0%22%5D%0A%20%20V%20--%3E%20C%5B%22%E5%8E%8B%E7%BC%A9%E7%8E%87%20C%2FT%22%5D%0A%20%20C%20--%3E%20L%5B%22%E5%90%8C%E6%A0%B7%E7%AA%97%E5%8F%A3%E8%A6%86%E7%9B%96%E7%9A%84%E5%AD%97%E7%AC%A6%22%5D%0A%20%20C%20--%3E%20F%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%20FLOPs%20%E6%8C%89%20token%22%5D%0A%20%20E%20--%3E%20M%5B%22%E6%98%BE%E5%AD%98%E4%B8%8E%E5%B0%BE%E9%83%A8%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20L%20--%3E%20MIX%5B%22%E5%90%84%E8%AF%AD%E7%A7%8D%E7%9C%9F%E5%AE%9E%E9%85%8D%E6%AF%94%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<h3 id="名额分配" tabindex="-1">名额分配 <a class="header-anchor" href="#名额分配" aria-label="Permalink to &quot;名额分配&quot;">​</a></h3><p>\\(V\\) 的增量给谁，比 \\(V\\) 本身更重要。BPE 把增量合并名额按全局频次分配，默认给高资源英语与模板。要给中文、代码运算符、数字完整形式留名额，必须在 tokenizer 训练集上对语言与代码做平衡采样——与 Xie 等人在预训练配比上做的事同构，只是发生在符号层。Unigram 用似然分配名额，高资源仍然占优，除非训练数据已平衡。显式保留字节回退（byte fallback）保证未登录可分解，等于永远占掉 256 个名额，换来稳健性。</p><p><span class="marginnote">数字切分值得单独政策。整年、整金额收成单 token，压缩好，但对逐位算术不友好；切成单数字，算术好，序列变长。许多模型折中为三位一组。这是任务先验写进词表，不是中性压缩。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>嵌入矩阵的参数是 \\(Vd\\)。对宽度 \\(d=4096\\)、\\(V=32000\\)，约 1.3 亿参数；\\(V=128000\\) 则四倍。对七十亿参数模型这已可见；对千亿模型相对更小，于是大模型更能「买得起」大词表换压缩。softmax 若做满 \\(V\\) 类，计算与 \\(V\\) 线性；实践常把输出与嵌入绑定，并依赖矩阵乘吞吐。真正的运行时税更多来自序列长度：注意力是 \\(n^2\\)，把 \\(n\\) 降 20% 比把 \\(V\\) 降 20% 通常更划算——前提是 KV 与计算已经是瓶颈。</p><p><span class="marginnote">把 \\(n\\) 降 20% 意味着注意力 FLOPs 降到 \\(0.8^2=0.64\\)，直接省 36%；而把 \\(V\\) 降 20% 只省 softmax 与嵌入的一小部分。两个旋钮的杠杆完全不同——序列长度动的是平方项，词表动的是线性项。</span></p><p>同一句话在大小词表下被切得多碎，解释了「按 token 配比」为何不公平：</p>',7)),(o(),r(E,null,{default:e(()=>[l(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E5%8F%A5%E8%AF%9D%20100%20%E5%AD%97%E7%AC%A6%22%5D%20--%3E%20EN%5B%22%E8%8B%B1%E8%AF%AD%E5%AD%90%E8%AF%8D%20%E7%BA%A6%2025%20token%22%5D%0A%20%20S%20--%3E%20ZH%5B%22%E4%B8%AD%E6%96%87%E5%B0%8F%E8%AF%8D%E8%A1%A8%20%E7%BA%A6%2080%20token%22%5D%0A%20%20S%20--%3E%20ZB%5B%22%E4%B8%AD%E6%96%87%E5%A4%A7%E8%AF%8D%E8%A1%A8%20%E7%BA%A6%2050%20token%22%5D%0A%20%20EN%20--%3E%20W%5B%22%E5%90%8C%E6%A0%B7%208K%20%E7%AA%97%E5%8F%A3%E8%A6%86%E7%9B%96%E5%AD%97%E7%AC%A6%E5%B7%AE%E6%95%B0%E5%80%8D%22%5D%0A%20%20ZH%20--%3E%20W%0A%20%20ZB%20--%3E%20W%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">这张图回答「为什么 10% 的中文 token 配比远小于 10% 的字符配比」：同样练一亿个 token，中文被切碎成更多格子，实际读到的汉字少得多。补偿要在 tokenizer 训练数据层面做，不是在预训练配比层面。</span></p><p>压缩改变有效深度：同样字符，更少的层间位置，意味着每个注意力头看到的「文档半径」更大。这会被误读成长上下文能力；它只是把半径的单位换成了更粗的符号。碎片化语言在同样 \\(n\\) 下半径更短，这是多语言不公平的机制来源之一。放大 \\(V\\) 给那些语言更多整词，是在符号层做配比补偿。</p><h3 id="与假重复、合成数据的相互作用" tabindex="-1">与假重复、合成数据的相互作用 <a class="header-anchor" href="#与假重复、合成数据的相互作用" aria-label="Permalink to &quot;与假重复、合成数据的相互作用&quot;">​</a></h3><p>高压缩词表会把教师模型的套话收成短路径，合成数据的模板重复在 token 空间里更密，MinHash 若按 token shingle，阈值要重校准。按字符 shingle 更稳定。Lee 式去重应在字符或字节层做一份，避免词表换代后近重复检测全部失效。合成数据若句式单一，还会「帮助」BPE 学到无意义的长合并，进一步假压缩。真实、多样的网页（FineWeb 一类）对词表健康有正面外部性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">常见误区：看到某模型上下文 8K token，就以为中文也能读 8K 字。中文若平均 1 token 只合 1 字，而英文 1 token 合 4 字符，实际能读的字符量差约 4 倍。跨语言比上下文长度，先查各语种的 \\(C/T\\)。</span></p><p>不要跨词表比较「训练了 \\(N\\) token」。报告字符数或文档数，或至少报告平均 \\(C/T\\)。不要在评测时对模型 A 用它自己的 tokenizer 数长度、对模型 B 用另一个，再谈长上下文谁赢。ByT5 的字符覆盖天然更长计数，比较时更要统一横轴。</p><p>\\(V\\) 不是越大越好：尾部符号梯度稀疏，可能变成几乎随机的嵌入，解码时偶发噪声。可以用最小频次门槛，把名额留给中频子词。聊天模板、工具调用、多模态哨兵会继续吃名额，应在定 \\(V\\) 时预留，而不是事后往 32K 里塞导致冲突。Gopher、Llama 公开的词表选择服务于当时的语言中心；做多语言产品时，应重测各语种 \\(C/T\\)，而不是继承一个英语最优 \\(V\\)。</p><p><span class="marginnote">嵌入与 LM 头绑定能省参数，但迫使输入输出共用几何。大词表下尾部词既当输入又当输出，两边都学不饱。解绑能给输出更多自由度，参数再加一份 \\(Vd\\)。这是优化器与词表的交界，下一篇 AdamW 管的是怎么衰减这些参数，而不是该不该绑。</span></p><p>最后，压缩率优化不能伤害可解释的边界。跨词合并（无空格预分词）可能把 <code>New York</code> 收成一块，对实体好，也可能把随机高频二元收成一块。应抽查词表里最高频的若干百个多词符号，确认它们不是未去重模板。Raffel 的 C4 清洗与 Broder/Lee 去重，在这里是词表质量的上游。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词表大小 \\(V\\) 同时买压缩率（更短序列）和付嵌入 / softmax 税；最优随模型规模与语言中心移动。</li><li>压缩率必须分语种、分代码报告；按 token 的配比不等于按字符的配比。</li><li>固定 token 预算偏向大词表，固定字符预算才比较「读了同样多文本」。</li><li>名额分配与 tokenizer 训练集配比同构；字节回退用 256 个名额换稳健。</li><li>ByT5 是低 \\(V\\)、低压缩的端点，用来对照子词到底省的是长度还是归纳偏置。</li><li>假压缩来自未去重模板与合成套话；词表训练必须放在清洗去重之后。</li><li>出处：Sennrich BPE；Kudo Unigram；Xue et al. ByT5；数据与去重对照 Raffel、Lee、Penedo；配比对照 Xie DoReMi 与 Gopher / Llama 的多语种实践。</li></ul>',12))])}const V=s(d,[["render",m]]);export{T as __pageData,V as default};
